_VALID_MODES = ("half_up", "half_even", "floor", "ceiling")


def round_div(numerator: int, denominator: int, mode: str = "half_up") -> int:
    """Divide two integers and round the quotient to an integer.

    Uses exact integer arithmetic (no floats). `denominator` must be positive.

    Rounding modes:
      * "half_up"   - round to nearest; exact halves round away from zero (default)
      * "half_even" - round to nearest; exact halves go to the even neighbour
      * "floor"     - round towards negative infinity
      * "ceiling"   - round towards positive infinity

    Raises ValueError if `denominator` <= 0 or `mode` is invalid.

    Examples:
        round_div(7, 2) == 4
        round_div(5, 2, "half_even") == 2
        round_div(-7, 2, "floor") == -4
    """
    if denominator <= 0:
        raise ValueError("denominator must be positive")
    if mode not in _VALID_MODES:
        raise ValueError(f"mode must be one of {_VALID_MODES}, got {mode!r}")

    if mode == "floor":
        return numerator // denominator
    if mode == "ceiling":
        return -((-numerator) // denominator)

    q, r = divmod(numerator, denominator)  # q = floor, 0 <= r < denominator
    twice_r = 2 * r

    if twice_r > denominator:
        return q + 1
    if twice_r < denominator:
        return q
    # exact half
    if mode == "half_up":
        if numerator >= 0:
            return q + 1
        return q
    # half_even: go to the even neighbour
    if q % 2 == 0:
        return q
    return q + 1
